   }
   if($action==='save'){
    $oldId=nibe_text($_POST['existing']??'',70);$old=$oldId!==''?($cat[$oldId]??null):null;if($oldId!==''&&!$old)throw new RuntimeException('Evento não encontrado.');if(!$old&&isset($cat[nibe_text($_POST['slug']??'',70)]))throw new RuntimeException('Este endereço já está cadastrado.');
