    if(($_FILES['banner']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){$name=nibe_upload($_FILES['banner'],($_SERVER['DOCUMENT_ROOT']??'').'/img/eventos/cadastrados');$e['banner']='/img/eventos/cadastrados/'.$name;}
    elseif(!$old||isset($_POST['use_existing_banner']))$e['banner']=nibe_text($_POST['banner_path']??'',250);
    if(!nibe_asset($e['banner']))throw new RuntimeException('Envie o banner ou selecione uma imagem já utilizada.');
